def slugify(text: str) -> str:
    s = text.strip().lower()
    out: list[str] = []
    pending_sep = False
    for ch in s:
        if ch.isalnum():
            if pending_sep:
                out.append('-')
                pending_sep = False
            out.append(ch)
        else:
            pending_sep = True
    return ''.join(out)

